import sys
from collections import defaultdict

sys.setrecursionlimit(200000)

def dfs(node, parent, graph, leaf_count):
    is_leaf = True
    for neighbor in graph[node]:
        if neighbor != parent:
            is_leaf = False
            dfs(neighbor, node, graph, leaf_count)
    if is_leaf:
        leaf_count[0] += 1

def solve():
    t = int(input().strip())
    results = []
    for _ in range(t):
        n, k = map(int, input().strip().split())
        friends = list(map(int, input().strip().split()))
        graph = defaultdict(list)
        for _ in range(n - 1):
            u, v = map(int, input().strip().split())
            graph[u].append(v)
            graph[v].append(u)

        leaf_count = [0]
        dfs(1, -1, graph, leaf_count)

        if leaf_count[0] <= k:
            results.append(-1)
        else:
            results.append(leaf_count[0] - k)

    for result in results:
        print(result)

solve()
